import React from 'react';

export default function PrivacyPolicy() {
  return (
    <div className="container py-24">
      <h1 className="font-display text-4xl font-bold mb-8">Privacy Policy</h1>
      <div className="prose prose-lg max-w-4xl text-gray-700">
        <p className="mb-4">Last Updated: {new Date().toLocaleDateString()}</p>

        <h2 className="text-2xl font-bold mt-8 mb-4">1. Information Collection</h2>
        <p>I only collect information you provide directly via the contact form (Name, Email, Message). This data is used solely to respond to your inquiries.</p>

        <h2 className="text-2xl font-bold mt-8 mb-4">2. Data Usage</h2>
        <p>Your data is never shared, sold, or used for marketing purposes. It is processed securely through Formspree and sent directly to my private email.</p>

        <h2 className="text-2xl font-bold mt-8 mb-4">3. Cookies</h2>
        <p>This website does not use tracking cookies or third-party analytics that store personal information.</p>

        <h2 className="text-2xl font-bold mt-8 mb-4">4. Your Rights</h2>
        <p>You can request to have your data deleted at any time by contacting me directly.</p>
      </div>
    </div>
  );
}
